blocks.draw:
var names = api.data.names, m = api.data.matrix, r = Math.min(api.width, api.height) / 2 - 40;
var root = api.el('g', { transform: 'translate(' + api.width / 2 + ' ' + api.height / 2 + ')' }, g);
var ch = api.d3.chord().padAngle(0.04).sortSubgroups(api.d3.descending)(m);
var arc = api.d3.arc().innerRadius(r).outerRadius(r + 12), rib = api.d3.ribbon().radius(r);
ch.forEach(function (c) { var p = api.el('path', { d: rib(c), style: 'fill: var(--s' + (c.source.index + 1) + '); fill-opacity: .45; stroke: var(--bg-elev)' }, root); api.tip(p, '<div class="t">' + names[c.source.index] + ' ↔ ' + names[c.target.index] + '</div>' + names[c.source.index] + ' → ' + names[c.target.index] + ': ' + c.source.value + '<br>' + names[c.target.index] + ' → ' + names[c.source.index] + ': ' + c.target.value); });
ch.groups.forEach(function (gr) { var p = api.el('path', { d: arc(gr), style: 'fill: var(--s' + (gr.index + 1) + ')' }, root); p.setAttribute('data-title', names[gr.index]); p.setAttribute('data-sub', gr.value + ' chamadas no total');
  var a = (gr.startAngle + gr.endAngle) / 2, x = Math.sin(a) * (r + 26), y = -Math.cos(a) * (r + 26); api.txt(root, x, y + 4, names[gr.index], 'small', a > Math.PI ? 'end' : 'start'); });
api.legend('Marcas', 'rib', { sw: 'band', label: 'Faixa = chamadas entre os dois' });

var pts = [], rnd = api.d3.randomNormal.source(api.d3.randomLcg(7));
for (var i = 0; i < 600; i++) pts.push([rnd(240, 60)(), rnd(150, 40)()]);
var hb = api.d3.hexbin().radius(14).extent([[0, 0], [api.width, api.height]]), bins = hb(pts), mx = api.d3.max(bins, function (b) { return b.length; });
bins.forEach(function (b) { var p = api.el('path', { d: 'M' + b.x + ',' + b.y + hb.hexagon(), style: 'fill: var(--accent); fill-opacity:' + (0.12 + 0.85 * b.length / mx).toFixed(2) + '; stroke: var(--bg-elev)' }, g); api.tip(p, b.length + ' cliques'); });
api.legend('Escala', 'hex', { sw: 'fill', label: 'Mais forte = mais cliques' });
